() => {
  const shell = document.querySelector('.display-shell');
  const clinicHeader = document.querySelector('.clinic-header');
  const queueHeader = document.querySelector('.queue-header');
  const labels = Array.from(document.querySelectorAll('.queue-stat-latest dt')).map((el) => {
    const r = el.getBoundingClientRect();
    return {
      text: el.textContent?.trim(),
      height: r.height,
      scrollWidth: el.scrollWidth,
      clientWidth: el.clientWidth,
      fontSize: getComputedStyle(el).fontSize,
    };
  });
  return {
    inner: {w: window.innerWidth, h: window.innerHeight},
    canvas: {
      w: shell?.getBoundingClientRect().width,
      h: shell?.getBoundingClientRect().height,
      minWidth: shell ? getComputedStyle(shell).minWidth : null,
      minHeight: shell ? getComputedStyle(shell).minHeight : null,
    },
    scroll: {
      w: document.documentElement.scrollWidth,
      h: document.documentElement.scrollHeight,
    },
    clinicBottom: clinicHeader?.getBoundingClientRect().bottom,
    queueTop: queueHeader?.getBoundingClientRect().top,
    labels,
  };
}

